import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String orgId = extractOrgFromSession(sessionToken);

        if (reportType == null || dateFrom == null || dateTo == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format
        if (!dateFrom.matches("\\d{4}-\\d{2}-\\d{2}") || !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("(transactions|settlements|chargebacks)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildReportQuery(reportType, orgId, dateFrom, dateTo, sortCol);
            log.info("Executing report query for org=" + orgId + " type=" + reportType);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                resp.setContentType("text/csv");
                resp.setHeader("Content-Disposition", "attachment; filename=report.csv");
                PrintWriter out = resp.getWriter();
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                for (int i = 1; i <= cols; i++) {
                    out.print(meta.getColumnName(i) + (i < cols ? "," : "\n"));
                }
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        String val = rs.getString(i);
                        out.print(escapeCsv(val) + (i < cols ? "," : "\n"));
                    }
                }
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String orgId, String from, String to, String sortCol) {
        // orgId comes from validated session, dates are regex-checked
        String base = "SELECT * FROM " + type + " WHERE org_id = '" + orgId +
                "' AND created_at BETWEEN '" + from + "' AND '" + to + "'";
        if (sortCol != null && !sortCol.isEmpty()) {
            // Allow dynamic sort for UX flexibility
            base += " ORDER BY " + sortCol;
        }
        return base;
    }

    private String escapeCsv(String val) {
        if (val == null) return "";
        if (val.contains(",") || val.contains("\"") || val.contains("\n")) {
            return "\"" + val.replace("\"", "\"\"") + "\"";
        }
        return val;
    }

    private boolean validateSession(String token) {
        // Validates against session store
        return token != null && token.length() == 64;
    }

    private String extractOrgFromSession(String token) {
        // In production, looks up org from session store
        // Returns org UUID like "a]f4e2d1-..."
        return "org_" + token.substring(0, 8);
    }
}
